import{_ as s,o as a,c as p,a3 as o}from"./chunks/framework.DdpBa4_E.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/programmer-essential/19-第19章—知己知彼-计算机的工作流程.md","filePath":"books/programmer-essential/19-第19章—知己知彼-计算机的工作流程.md","lastUpdated":1781445373000}'),n={name:"books/programmer-essential/19-第19章—知己知彼-计算机的工作流程.md"};function i(t,e,r,l,c,d){return a(),p("div",null,[...e[0]||(e[0]=[o(`<p>在<a href="https://juejin.cn/book/7196580339181944872/section/7196589491266519080" target="_blank" rel="noreferrer">第 6 章</a>我们讲过<strong>代码的执行流程</strong>，我们知道代码是被编译成机器指令，然后在 CPU 中一条一条被执行的。</p><p>那么，在这个过程中，计算机是怎么执行的呢？或者说，从代码被编写开始，到代码被运行出结果为止，这中间经历了什么呢？</p><p>接下来我们就来了解下。</p><h2 id="另类的计算机定义" tabindex="-1">另类的计算机定义 <a class="header-anchor" href="#另类的计算机定义" aria-label="Permalink to &quot;另类的计算机定义&quot;">​</a></h2><p>我们都知道，计算机是由<code>控制器</code>、<code>运算器</code>、<code>存储器</code>、<code>输入设备</code>、<code>输出设备</code>这五部分组成的。</p><p>这太难记了，我们可以再宏观一些：<strong>计算机是由<code>输入系统</code>、<code>输出系统</code>、<code>运算系统</code>这三部分组成的</strong>。</p><p>站在程序员的角度来说，我把我的代码<code>输入</code>给计算机，计算机自己<code>计算</code>后，把结果<code>输出</code>给我，这就完事了。也就是说，我并不知道计算机内部发生了什么，我只知道我给它数据，它计算，算完把结果给我，所以，对于我来说，计算机就是个黑盒子，它就有三个功能：<strong>接受输入、进行运算、输出结果</strong>，如此而已。</p><p>这就不能叫冯·诺伊曼结构了，你可以叫它入算出结构，如果给点面子的话，你可以叫它奔波儿灞取经结构。</p><p>OK，到这里，我们就知道计算机的三个核心功能了：<strong>输入、运算、输出</strong>。</p><h2 id="计算机的工作流程" tabindex="-1">计算机的工作流程 <a class="header-anchor" href="#计算机的工作流程" aria-label="Permalink to &quot;计算机的工作流程&quot;">​</a></h2><p>那么，计算机的工作流程是什么样的呢？比如，我给它一段代码，它是怎么干的呢？</p><p>从大方面看，就是三个步骤：</p><ol><li>读入你写的代码，也就是<code>输入</code>，至于怎么读，读到哪，先别管；</li><li>执行读入的代码，也就是<code>运算</code>，至于怎么运算的，也先别管；</li><li>将运算的结果展示出来，也就是<code>输出</code>，至于怎么展示的，也先别管。</li></ol><p>好，大步骤我们知道了，我们就来看下每个小步骤是怎么执行的。</p><h3 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h3><p>现在我打开编辑器写了如下代码：</p><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Hello</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sayHello</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        System.out.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">println</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;hello, world&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>然后点击运行，结果就出来了。</p><p>那么，这块代码是怎么被读入计算机的呢？</p><p>首先，我们知道，我们写的这块代码是个后缀名为<code>.java</code>的文件，存放在我们电脑上的磁盘中。而代码要执行的时候，就会把它读入内存中，怎么读入呢？你可以理解为就跟普通的文件读写一样，通过 IO 操作读入内存中。好，现在我们的代码已经从磁盘中到内存中了，也就是已经完成了<strong>输入</strong>阶段了。</p><blockquote><p>Tips：Java 代码具有跨平台性，<code>.java</code> 文件先被编译成<code>.class</code>文件，然后读入到 JVM 中，而 JVM 就是运行在内存中的。</p></blockquote><p>接下来，我们来看运算的过程。</p><h3 id="运算" tabindex="-1">运算 <a class="header-anchor" href="#运算" aria-label="Permalink to &quot;运算&quot;">​</a></h3><p>现在，我们的代码已经在内存中了，接下来，我们就要开始运算了。</p><p><a href="https://juejin.cn/book/7196580339181944872/section/7196589491266519080" target="_blank" rel="noreferrer">第 6 章</a>我们说过，计算机执行的是机器码，而我们读入的并不是机器码啊，这怎么可能执行呢？</p><p>所以，我们运算的第一步，就是将非机器码转换为机器码，也就是我们写的代码，转换为 0110 这种二进制。其实，<strong>代码是先经过编译器转换为汇编语言，然后再经过汇编处理，才能变换为机器码</strong>。</p><p>好，现在，我们的代码已经从自己写的语言变换为二进制了，那么接下来就是运算了。</p><p>还记得我们<a href="https://juejin.cn/book/7196580339181944872/section/7196589491266519080" target="_blank" rel="noreferrer">第 6 章</a>讲的机器指令吗，没错，这里的运算就要用到那些指令了。</p><p>我们得到的机器码，里面就包含这些指令，以及这些指令要操作的数，那么，计算机就用这些指令来操作对应的数字，就得到了最后的结果，那么接下来，就只需要把这些结果输出就行了。</p><p>等等等等，你这不对啊，你说的是单纯的数字计算和打印，比如我要是写个页面呢？页面最后得显示出来吧，那页面也是输出啊，这页面是怎么计算的？</p><p>好，我们就来看<code>页面（以下统称为 UI）</code>的计算过程。</p><p>首先，不管你是 UI 还是非 UI，你的输入过程都是一样的，都是将自己写的文件读入内存，然后转换为机器码，这个就不废话了。</p><p>对于 UI 来说，我们把 UI 当成一块块的 UI 单元，也就是一个个的矩形块，这些矩形块有的显示文字，有的显示图像，有的只是单纯地用来排版其他矩形块，这个应该都能理解。</p><p>不管是什么样的 UI 单元，其核心属性就是这么几点：</p><ul><li><code>尺寸</code>，也就是宽高；</li><li><code>位置</code>，也就是自己在屏幕上的坐标；</li><li><code>内容</code>，也就是自己要显示的内容。</li></ul><p>那么，UI 单元的内容是啥子呢？</p><p>其实就是<strong>像素点</strong>！我们的 UI 单元是一个个的像素点组成的，可以理解为一个个的彩色小点，这些点都存储着自己的颜色值，是一个 32 位数字，高 8 位存储透明度值，接下来 8 位存放红色值，再接下来 8 位存放绿色植，最后 8 位存放蓝色值，所以也叫 ARGB。</p><p>所以，我们的 UI 就像一张大纸，从上到下密密麻麻地铺满了很多小点，我们 UI 的绘制其实就是遍历一个个的小点，然后将对应的颜色取出来画到屏幕上而已。</p><p>没错，正是这样！</p><p>那这是谁画的呢？屏幕！</p><p>那你运算器运算了啥啊？</p><p>我们写的 UI 肯定不是写死的坐标，而是使用各种不同的布局，然后加上各种各样的内边距（padding）、外边距（margin）等来排版，这就是运算器要运算的了。</p><p>再比如，我们写的宽高等不是固定值，而是包括内容、百分比等，这些也是 UI 要计算的。</p><p>它会将我们写的这些边距、尺寸等，计算成复合当前屏幕的固定值，然后保存起来，交给屏幕去渲染。</p><blockquote><p>Tips：其实图形的计算，不是 CPU 干的，而是 GPU 干的，因为 CPU 不适合做图像计算。</p></blockquote><p>所以，你 CPU 很屌但是玩游戏卡，就是 GPU 不行，因为游戏需要大量的图像计算，所以需要很屌的 GPU，也就是需要个好显卡。</p><p>不管是谁算的，总之都是计算机算的，计算机将 UI 数据计算好后，会保存起来，保存到一个 Bitmap 上，或者说保存到一个矩阵中，然后交给屏幕去绘制。</p><p>接下来就是输出了。</p><h3 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h3><p>输出也分为两种：UI 类型的和非 UI 类型的。</p><p><code>非 UI 类型</code>的比较简单，我们直接从内存读出数据后，打印出来即可。或者直接将结果写到电脑文件上即可，这就意味着数据又从内存中回到磁盘中了。</p><p>那么，<code>UI 类型</code>的呢？就比较费劲了，我们的屏幕需要定时从内存中读出数据，然后将其绘制出来，那为啥不是一次绘制呢？因为一次干不完啊。</p><p>你这么理解，我们的 UI 数据在运算之后，保存到了矩阵中，我们的屏幕就定期从这个矩阵中从上到下，一行一行地读出数据，也就是像素点，然后将其绘制在屏幕上，这样的一屏幕数据，叫做<strong>一帧</strong>。</p><p>那么，这个定期时间是多长呢？</p><p>就看你的<strong>屏幕刷新率</strong>了，比如，如果你的屏幕刷新率是 60HZ，那就等于 1 秒内（1000ms）要绘制 60 次，也就是每 16ms 就要绘制一次（1000/60=16），所以这个定时时间就是 16ms；如果你的屏幕刷新率是 120HZ，那就等于 1 秒内绘制 120 次，所以每 8ms 就要绘制一次。</p><p>所以，这个时间取决于屏幕刷新率。</p><p>有人说，这 1 秒要绘制 60 次，那就意味着 CPU 在 1 秒内要计算 60 次啊，那它后面的数据不会把前面的覆盖了吗？</p><p>比如，CPU 计算了第一帧，屏幕去绘制了，还没绘制完，CPU 就计算出了第二帧，然后把第一帧覆盖了，这不就乱了吗？</p><p>没错，这样会乱，这个就叫做屏幕的<strong>撕裂</strong>。</p><p>所以，我们就开辟了<strong>缓存</strong>，CPU 计算完一帧数据后，直接放在缓存中即可，屏幕画完就从缓存中取出下一条接着画。</p><p>那你这缓存多大呢？比如你设置为 10，CPU 可能都计算了 11 条了，你这第 1 条还没画完，这不就还是覆盖吗？</p><p>对啊，所以问题的核心是啥呢？是 CPU 和屏幕自己干自己的，速度不同步。</p><p>你看，这是不是跟我们<a href="https://juejin.cn/book/7196580339181944872/section/7196590941707173923" target="_blank" rel="noreferrer">第 17 章</a>中讲的 TCP 的停止等待协议很像呢？此时 CPU 是发送方，屏幕是接收方，屏幕来不及处理，CPU 就发送下一条数据了。</p><p>所以怎么解决呢？</p><p><strong>停止等待协议</strong>！</p><blockquote><p>Tips: 学会类比，举一反三，融会贯通，就能迅速扩大知识面，并且记得更牢。</p></blockquote><p>OK，我们也来让 CPU 和屏幕停止等待一下！首先 CPU 绘制完后，就将数据放进缓冲区，然后停下来等着；我们再让屏幕每次绘制完后，给 CPU 发个信号，告诉 CPU：劳资画完了，你可以开始了。这个时候，CPU 就继续绘制，并将新数据放入缓存中。</p><p>那么，这个缓存的大小是多少呢？</p><p>因为我们有两个同时干活的，所以缓冲区大小给 <code>2</code> 就行了，这样可以保证他俩同时工作。这两个缓冲区一个叫<code>后缓冲，供 CPU 计算</code>；一个叫<code>前缓冲，供屏幕绘制</code>。</p><p>CPU 不断向后缓冲写入数据，屏幕不断从前缓冲取出数据绘制，绘制完就发送信号给 CPU 计算下一帧，CPU 接到信号后就交换前后缓冲数据，并接着计算下一帧数据。就这样循环往复，我们眼前就出现了不断变化的画面。</p><p>这个信号就叫做 <strong>VSYNC</strong>，也就是<strong>垂直同步信号</strong>。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本章从宏观角度讲了计算机的工作流程：<strong>输入-&gt;运算-&gt;输出</strong>。</p><ul><li>输入：将磁盘上的文件读入到内存中。</li><li>运算：将读入的数据转换为机器码并执行。</li><li>输出：将执行的结果输出到磁盘或屏幕上。</li></ul><p>并且，我们重点讲了 UI 类型的运算和输出过程，这里面有个很重要的点：<strong>发送方和接收方速率不同的情况下就采用停止等待协议</strong>，这其实可以高度抽离一下，也就是<strong>生产者消费者模型</strong>，这是一个很重要的模型，比方说本章的 CPU 和屏幕的关系，<a href="https://juejin.cn/book/7196580339181944872/section/7196590941707173923" target="_blank" rel="noreferrer">第 17 章</a>的 TCP 协议中发送方和接收方的关系，还有<a href="https://juejin.cn/book/7196580339181944872/section/7196591134489968692" target="_blank" rel="noreferrer">第 14 章</a>讲到的多个线程之间的资源竞争，都是需要等待和唤醒的。</p><p>这就是<code>类比思想</code>，知识其实不多，就那么点，就看你是否能联想到一起，这一点我们会在后面的第 34 章专门讲解。那么下一章，我们就来看下计算机的内存设计和缓存设计是怎么实现的。</p>`,76)])])}const g=s(n,[["render",i]]);export{k as __pageData,g as default};
